with Src as (select *, case when plan in ('standard', 'premium') then 'Group A' else 'Other' end as plan_group from subscriptions where customer_id is not null or end_date <= '2024-09-01'), EndQuarterSummary as (select quarter(end_date) as end_quarter, plan, round(stddev(monthly_fee), 2) as stddev_monthly_fee, count(monthly_fee) as monthly_fee_count from Src group by quarter(end_date), plan) select end_quarter, plan, monthly_fee_count from EndQuarterSummary order by plan, end_quarter limit 5;
